//! The brush alphas shipped with the application: grayscale dab shapes generated by
//! code, so that their license is clear (CC0, generated by Patine).
//!
//! A stroke refers to its alpha by the hash of its PNG bytes, stored in the project
//! (see `patine_core::commands::PaintStroke`): projects never depend on the shipped set.
//! A round dab needs no alpha (its hardness shapes it).

use std::sync::Arc;

use patine_core::resource::{Resource, ResourceHash, ResourceKind};
use thiserror::Error;

/// Side of the generated alphas, in pixels.
pub const ALPHA_SIZE: u32 = 128;

/// License of the generated alphas.
pub const LICENSE: &str = "CC0-1.0 (generated by Patine)";

/// One shipped alpha.
#[derive(Clone, Copy, Debug)]
pub struct AlphaDef {
    /// Stable identifier, also the resource name (`<id>.png`).
    pub id: &'static str,
    /// Translation key of its name.
    pub name_key: &'static str,
    generate: fn(f32, f32) -> f32,
}

impl PartialEq for AlphaDef {
    /// Alphas are equal when their identifiers are.
    fn eq(&self, other: &Self) -> bool {
        self.id == other.id
    }
}

impl Eq for AlphaDef {}

/// A grayscale alpha, row by row from the top, 0 to 255.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct AlphaImage {
    /// Width in pixels.
    pub width: u32,
    /// Height in pixels.
    pub height: u32,
    /// Values, row by row.
    pub pixels: Vec<u8>,
}

/// An alpha that could not be read.
#[derive(Debug, Error)]
#[error("brush alpha cannot be read: {0}")]
pub struct AlphaError(String);

fn smoothstep(edge0: f32, edge1: f32, x: f32) -> f32 {
    let t = ((x - edge0) / (edge1 - edge0)).clamp(0.0, 1.0);
    t * t * (3.0 - 2.0 * t)
}

/// A small integer hash (PCG step), for the random shapes.
fn hash(mut v: u32) -> u32 {
    v = v.wrapping_mul(747_796_405).wrapping_add(2_891_336_453);
    let word = ((v >> ((v >> 28) + 4)) ^ v).wrapping_mul(277_803_737);
    (word >> 22) ^ word
}

fn random(seed: u32) -> f32 {
    (hash(seed) >> 8) as f32 / (1u32 << 24) as f32
}

/// A square with soft edges.
fn square(x: f32, y: f32) -> f32 {
    1.0 - smoothstep(0.8, 1.0, x.abs().max(y.abs()))
}

/// A cluster of soft drops.
fn splatter(x: f32, y: f32) -> f32 {
    (0..24u32)
        .map(|i| {
            let angle = random(i * 3) * std::f32::consts::TAU;
            let distance = random(i * 3 + 1).sqrt() * 0.7;
            let radius = 0.06 + random(i * 3 + 2) * 0.18;
            let (cx, cy) = (angle.cos() * distance, angle.sin() * distance);
            let d = ((x - cx).powi(2) + (y - cy).powi(2)).sqrt();
            1.0 - smoothstep(radius * 0.7, radius, d)
        })
        .fold(0.0, f32::max)
}

/// Sparse grains inside a soft disk.
fn grain(x: f32, y: f32) -> f32 {
    let px = ((x * 0.5 + 0.5) * ALPHA_SIZE as f32) as u32;
    let py = ((y * 0.5 + 0.5) * ALPHA_SIZE as f32) as u32;
    let noise = random(px.wrapping_mul(7919) ^ py.wrapping_mul(104_729));
    let disk = 1.0 - smoothstep(0.6, 1.0, (x * x + y * y).sqrt());
    if noise > 0.6 { disk } else { 0.0 }
}

/// A flat soft ellipse, like a chisel tip.
fn chisel(x: f32, y: f32) -> f32 {
    let d = (x * x + (y * 4.0).powi(2)).sqrt();
    1.0 - smoothstep(0.7, 1.0, d)
}

/// The shipped alphas.
pub const ALPHAS: [AlphaDef; 4] = [
    AlphaDef {
        id: "alpha.square",
        name_key: "alpha-square",
        generate: square,
    },
    AlphaDef {
        id: "alpha.splatter",
        name_key: "alpha-splatter",
        generate: splatter,
    },
    AlphaDef {
        id: "alpha.grain",
        name_key: "alpha-grain",
        generate: grain,
    },
    AlphaDef {
        id: "alpha.chisel",
        name_key: "alpha-chisel",
        generate: chisel,
    },
];

/// The shipped alpha `id`.
pub fn find(id: &str) -> Option<&'static AlphaDef> {
    ALPHAS.iter().find(|alpha| alpha.id == id)
}

impl AlphaDef {
    /// The alpha's pixels, sampled at pixel centers over [-1, 1]².
    pub fn image(&self) -> AlphaImage {
        let size = ALPHA_SIZE;
        let pixels = (0..size * size)
            .map(|i| {
                let x = ((i % size) as f32 + 0.5) / size as f32 * 2.0 - 1.0;
                let y = ((i / size) as f32 + 0.5) / size as f32 * 2.0 - 1.0;
                ((self.generate)(x, y).clamp(0.0, 1.0) * 255.0).round() as u8
            })
            .collect();
        AlphaImage {
            width: size,
            height: size,
            pixels,
        }
    }

    /// The alpha as a project resource: a grayscale PNG, and its hash.
    pub fn resource(&self) -> (ResourceHash, Resource) {
        let image = self.image();
        let mut bytes = Vec::new();
        let gray = image::GrayImage::from_raw(image.width, image.height, image.pixels)
            .expect("the generated pixels fill the image");
        gray.write_to(
            &mut std::io::Cursor::new(&mut bytes),
            image::ImageFormat::Png,
        )
        .expect("encoding a PNG in memory does not fail");
        Resource::new(
            format!("{}.png", self.id),
            ResourceKind::Image,
            Arc::from(bytes),
        )
    }
}

/// Reads an alpha resource (any image format the build decodes; color is averaged to
/// gray by luminance).
pub fn decode(bytes: &[u8]) -> Result<AlphaImage, AlphaError> {
    let image = image::load_from_memory(bytes).map_err(|error| AlphaError(error.to_string()))?;
    let gray = image.to_luma8();
    Ok(AlphaImage {
        width: gray.width(),
        height: gray.height(),
        pixels: gray.into_raw(),
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn alphas_are_deterministic_and_read_back() {
        for alpha in &ALPHAS {
            let (hash, resource) = alpha.resource();
            assert_eq!(alpha.resource().0, hash, "{} is stable", alpha.id);
            let image = decode(&resource.bytes).expect("a PNG");
            assert_eq!(image, alpha.image(), "{}", alpha.id);
            assert_eq!(find(alpha.id), Some(alpha));
        }
        let ids: std::collections::HashSet<_> = ALPHAS.iter().map(|a| a.id).collect();
        assert_eq!(ids.len(), ALPHAS.len());
    }

    #[test]
    fn alphas_have_a_shape() {
        for alpha in &ALPHAS {
            let image = alpha.image();
            let size = image.width as usize;
            let painted = image.pixels.iter().filter(|v| **v > 128).count();
            assert!(painted > size * size / 50, "{} paints something", alpha.id);
            // The border stays empty, so that dabs have no visible square edge.
            let border =
                (0..size).flat_map(|i| [image.pixels[i], image.pixels[(size - 1) * size + i]]);
            assert!(border.into_iter().all(|v| v < 16), "{} fades out", alpha.id);
        }
        assert!(decode(b"not an image").is_err());
    }
}
